generata:
GET COLLECTION voyages;
FILTER CASE WHERE .is_delayed = TRUE;
SAVE AS delayed_voyages@ft_en_072;
GET COLLECTION voyages;
FILTER CASE WHERE .departure = 'Genova';
SAVE AS genova_voyages@ft_en_072;
INTERSECT COLLECTIONS delayed_voyages@ft_en_072, genova_voyages@ft_en_072;

GET COLLECTION sub2;
FILTER CASE WHERE .cargo_details.hazard = TRUE;
SAVE AS dangerous@ft_en_072;
GET COLLECTION delayed_voyages;
FILTER CASE WHERE .is_delayed = TRUE;
SAVE AS delayed@ft_en_072;
MERGE COLLECTIONS dangerous@ft_en_072, delayed@ft_en_072 REMOVE DUPLICATES;
